/// Vector asset generator for Dutch iDEAL / Wero transition branding.
///
/// Implements the official co-branded iDEAL | Wero lockups published by
/// Currence iDEAL / EPI during the European Wero migration:
/// https://ideal.nl/naar-wero
class IdealAssets {
  IdealAssets._();

  /// Renders the official horizontal co-branded iDEAL | Wero lockup logo.
  static Widget logo({
    IdealColor color = IdealColor.yellow,
    double height = 24.0,
  }) {
    final isDark = color == IdealColor.black;
    return SvgPicture.string(
      isDark ? _idealWeroDarkSvg : _idealWeroLightSvg,
      height: height,
      fit: BoxFit.contain,
    );
  }

  /// Renders the standalone iconic iDEAL emblem badge for compact button presentations.
  static Widget emblem({
    IdealColor color = IdealColor.yellow,
    double height = 24.0,
  }) {
    return SvgPicture.string(
      _idealEmblemSvg,
      height: height,
      fit: BoxFit.contain,
    );
  }

